// Local optimized asset references (generated via gen-images.mjs -> projectImageManifest.json)
// Static JS manifest (generated by gen-images.mjs). Falls back to empty object if missing.
import manifestModule from './projectImageManifest.mjs'
const manifest = manifestModule || {}

// Resolve base URL: Vite provides import.meta.env.BASE_URL, Node.js scripts use '/'
const BASE = (typeof import.meta.env !== 'undefined' && import.meta.env.BASE_URL) || '/'

/**
 * Projects with T-Shaped Spectrum Scores
 * 
 * Each project has a spectrum score indicating the balance of:
 * - design: Visual/creative aspects (0-100)
 * - tech: Technical/engineering aspects (0-100)
 */
export const projects = [
  { 
    id: 1, 
    slug: 'defi-yield-optimizer', 
    base: 'studio-identity', 
    title: 'DeFi Yield Optimizer Platform', 
    desc: 'Advanced DeFi platform with automated yield farming, smart contract integration, and real-time analytics dashboard.', 
    color: '#ffd6e0', 
    category: 'Blockchain Development', 
    year: 2025,
    spectrum: { design: 35, tech: 95 }
  },
  { 
    id: 2, 
    slug: 'urubay-saas-platform', 
    base: 'interactive-portfolio', 
    title: 'Urubay SaaS Platform', 
    desc: 'Microservices-based SaaS platform with AI integration and Event-Driven Architecture.', 
    color: '#e7ffd8', 
    category: 'SaaS Development', 
    year: 2024,
    spectrum: { design: 50, tech: 90 }
  },
  { 
    id: 3, 
    slug: 'ecommerce-optimization', 
    base: 'ecommerce-platform', 
    title: 'E-commerce Performance Platform', 
    desc: 'High-performance e-commerce solution with advanced analytics and conversion optimization.', 
    color: '#d7f0ff', 
    category: 'E-commerce Development', 
    year: 2024,
    spectrum: { design: 65, tech: 80 }
  },
  { 
    id: 4, 
    slug: 'brand-is-code', 
    base: 'packaging-design', 
    title: 'Brand is Code Solutions', 
    desc: 'Custom web applications and WordPress solutions for business clients.', 
    color: '#fff2d7', 
    category: 'Web Development', 
    year: 2023,
    spectrum: { design: 75, tech: 70 }
  },
].map(p => ({
  ...p,
  thumb: manifest[p.base]?.thumb || '',
  avif: Object.entries(manifest[p.base]?.avif || {}).map(([w,name])=>`${import.meta.env.BASE_URL}projects/${name} ${w}w`).join(', '),
  webp: Object.entries(manifest[p.base]?.webp || {}).map(([w,name])=>`${import.meta.env.BASE_URL}projects/${name} ${w}w`).join(', '),
  jpg: Object.entries(manifest[p.base]?.jpg || {}).map(([w,name])=>`${import.meta.env.BASE_URL}projects/${name} ${w}w`).join(', '),
  image: manifest[p.base]?.jpg?.['1200'] ? `${import.meta.env.BASE_URL}projects/${manifest[p.base].jpg['1200']}` : ''
}))

export function getProjectById(id) {
  const num = Number(id)
  return projects.find(p => p.id === num)
}
